// Analyze message and determine required agents
const message = $json.message.toLowerCase();
const user = $json.user_id;
const username = $json.username;

let agents = [];
let intent = 'unknown';

// Trading intents
if (message.includes('buy') || message.includes('sell') || message.includes('trade')) {
  agents.push('AGENT-TRADING212');
  intent = 'trading';
}

// Analysis intents
if (message.includes('analyze') || message.includes('predict') || message.includes('rsi') || message.includes('ema')) {
  agents.push('AGENT-TECHNICAL-ANALYSIS');
  intent = 'analysis';
}

// Portfolio intents
if (message.includes('portfolio') || message.includes('holdings') || message.includes('allocation')) {
  agents.push('AGENT-PORTFOLIO-MANAGER');
  intent = 'portfolio';
}

// Market data intents
if (message.includes('price') || message.includes('news') || message.includes('market')) {
  agents.push('AGENT-MARKET-DATA');
  intent = 'market';
}

// Research intents
if (message.includes('research') || message.includes('fundamentals') || message.includes('earnings')) {
  agents.push('AGENT-RESEARCH');
  intent = 'research';
}

return {
  user_id: user,
  username: username,
  message: $json.message,
  intent: intent,
  agents_needed: agents,
  timestamp: new Date().toISOString()
};

// Wait for agent responses and synthesize
const responses = $json;

const synthesized = `
Based on analysis:

${responses.map(r => r.agent_response).join('\n\n')}

Recommendation: ${responses[0].recommendation || 'See details above'}
`;

return {
  response: synthesized,
  agents_used: responses.map(r => r.agent),
  user_id: $json[0].user_id
};
